CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK (role IN ('CLIENT','PROFESSIONAL')),state TEXT,city TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS professional_profiles (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id),profession TEXT NOT NULL CHECK (profession IN ('ADVOCATE','CHARTERED_ACCOUNTANT')),specialization TEXT NOT NULL,bio TEXT,state TEXT,city TEXT,years_experience INTEGER NOT NULL DEFAULT 0,hourly_rate INTEGER NOT NULL DEFAULT 0,verified INTEGER NOT NULL DEFAULT 0,verification_body TEXT,registration_no TEXT,membership_tier TEXT NOT NULL DEFAULT 'BRONZE' CHECK (membership_tier IN ('BRONZE','SILVER','GOLD','PLATINUM')),completed_agreements INTEGER NOT NULL DEFAULT 0,avg_response_minutes INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS agreements (id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER NOT NULL REFERENCES users(id),professional_id INTEGER NOT NULL REFERENCES professional_profiles(id),scope TEXT NOT NULL,fee_in_paise INTEGER NOT NULL,commission_rate REAL NOT NULL DEFAULT 0.10,status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SIGNED','COMPLETED','CANCELLED')),client_signed_at TEXT,professional_signed_at TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS membership_payments (id INTEGER PRIMARY KEY AUTOINCREMENT,professional_id INTEGER NOT NULL REFERENCES professional_profiles(id),tier TEXT NOT NULL CHECK (tier IN ('BRONZE','SILVER','GOLD','PLATINUM')),amount_in_paise INTEGER NOT NULL,provider TEXT NOT NULL CHECK (provider IN ('razorpay','stripe','demo')),provider_ref TEXT,status TEXT NOT NULL DEFAULT 'CREATED' CHECK (status IN ('CREATED','PAID','FAILED')),created_at TEXT NOT NULL DEFAULT (datetime('now')),paid_at TEXT);
